from ta_moler.cmd.unix_syslog.start_syslog import StartSyslog


class TaMolerTailLastLog(StartSyslog):
    """Tail Last Log."""

    def __init__(self, connection, prompt=None, port=None, path="/tmp/btslog2", mask="'SYSLOG_*'", console=True,
                 newline_chars=None, runner=None, time_for_failure=0.1, inactivity_timeout=725.0, command_path="/tmp/"):
        """
        Tail last log command.

        :param connection: Moler connection to device, terminal when command is executed.
        :param port: port for server to listen. None if no server to start.
        :param path: path to logs from btslog
        :param mask: mask for log files
        :param console: set True to print on console. False to not print.
        :param prompt: prompt (on system where command runs).
        :param newline_chars: Characters to split lines - list.
        :param runner: Runner to run command.
        :param time_for_failure: time (in seconds) for failure indication from first line of output. Set to 0 if skip
        all failure indications.
        :param inactivity_timeout: time (in seconds) when no data is sent by connection within this time then command
        will be break
        :param command_path: path to command. Set None if additional path is not needed.
        """
        super(TaMolerTailLastLog, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                                 runner=runner, time_for_failure=time_for_failure,
                                                 inactivity_timeout=inactivity_timeout)
        self.port = port
        self.path = path
        self.mask = mask
        self.console = console
        self.command_path = command_path

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "ta_moler_tail_last_log.py"
        if self.console:
            cmd = f"{cmd} -c y"
        else:
            cmd = f"{cmd} -c n"
        if self.port:
            cmd = f"{cmd} -p {self.port}"
        if self.path:
            cmd = f"{cmd} -d {self.path}"
        if self.mask:
            cmd = f"{cmd} -m {self.mask}"
        return cmd


COMMAND_OUTPUT = """
/tmp/ta_moler_tail_last_log.py -c y -d /tmp/btslog2 -m 'SYSLOG_*'
user@server:~>"""

